tool_schemas.implementation:
def summarize_youtube_video(youtube_video_id=None, source_url=None, model_id=None, prompt_version=None, temperature=None, max_output_tokens=None, force_regenerate=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0554000" if __import__("os").path.isdir("./environment_mix/0554000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _new_id(prefix):
        return prefix + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")

    def _log(status, details=None, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("ytv_req_"),
            "endpoint": "summarize_youtube_video",
            "status": status,
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id
        }
        if details is not None:
            row["details"] = details
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_youtube_id(url):
        if not isinstance(url, str) or not url.strip():
            return None
        try:
            u = urllib.parse.urlparse(url.strip())
        except Exception:
            return None
        host = (u.netloc or "").lower()
        path = u.path or ""
        q = urllib.parse.parse_qs(u.query or "")
        if "youtu.be" in host:
            seg = path.strip("/").split("/")
            return seg[0] if seg and seg[0] else None
        if "youtube.com" in host or "m.youtube.com" in host:
            if "v" in q and q["v"] and q["v"][0]:
                return q["v"][0]
            m = re.match(r"^/shorts/([^/?#]+)", path)
            if m:
                return m.group(1)
            m = re.match(r"^/embed/([^/?#]+)", path)
            if m:
                return m.group(1)
        return None

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    # --- Validate oneOf: allow both when consistent (audit defect fix) ---
    if youtube_video_id is None and source_url is None:
        _log("VALIDATION_ERROR", {"reason": "missing_youtube_video_id_or_source_url"})
        return _err("VALIDATION_ERROR", "Provide either youtube_video_id or source_url.")
    if youtube_video_id is not None and not isinstance(youtube_video_id, str):
        _log("VALIDATION_ERROR", {"field": "youtube_video_id"})
        return _err("VALIDATION_ERROR", "youtube_video_id must be a string.", field="youtube_video_id")
    if source_url is not None and not isinstance(source_url, str):
        _log("VALIDATION_ERROR", {"field": "source_url"})
        return _err("VALIDATION_ERROR", "source_url must be a string.", field="source_url")

    ytid_from_url = _parse_youtube_id(source_url) if source_url is not None else None
    resolved_ytid = None
    normalized_source_url = None

    if youtube_video_id is not None and source_url is not None:
        if ytid_from_url is None:
            _log("VALIDATION_ERROR", {"reason": "unparseable_source_url"})
            return _err("VALIDATION_ERROR", "source_url is not a recognized YouTube URL.", field="source_url")
        if youtube_video_id.strip() != ytid_from_url:
            _log("VALIDATION_ERROR", {"reason": "youtube_video_id_source_url_mismatch", "parsed": ytid_from_url})
            return _err("VALIDATION_ERROR", "youtube_video_id and source_url refer to different videos.", field="source_url")
        resolved_ytid = youtube_video_id.strip()
        normalized_source_url = source_url.strip()
    elif youtube_video_id is not None:
        resolved_ytid = youtube_video_id.strip()
    else:
        if ytid_from_url is None:
            _log("VALIDATION_ERROR", {"reason": "unparseable_source_url"})
            return _err("VALIDATION_ERROR", "source_url is not a recognized YouTube URL.", field="source_url")
        resolved_ytid = ytid_from_url
        normalized_source_url = source_url.strip()

    if not resolved_ytid:
        _log("VALIDATION_ERROR", {"reason": "empty_youtube_video_id"})
        return _err("VALIDATION_ERROR", "youtube_video_id is required after resolution.", field="youtube_video_id")

    # --- Validate model / prompt / generation params ---
    if model_id is not None:
        if not isinstance(model_id, str) or not re.match(r"^ytv_mdl_01H[0-9A-Z]{15,}$", model_id):
            _log("VALIDATION_ERROR", {"field": "model_id"})
            return _err("VALIDATION_ERROR", "model_id has invalid format.", field="model_id")
    if prompt_version is not None and not isinstance(prompt_version, str):
        _log("VALIDATION_ERROR", {"field": "prompt_version"})
        return _err("VALIDATION_ERROR", "prompt_version must be a string.", field="prompt_version")
    if temperature is not None:
        if not isinstance(temperature, (int, float)) or temperature < 0.0 or temperature > 2.0:
            _log("VALIDATION_ERROR", {"field": "temperature"})
            return _err("VALIDATION_ERROR", "temperature must be between 0.0 and 2.0.", field="temperature")
        temperature = float(temperature)
    if max_output_tokens is not None:
        if not isinstance(max_output_tokens, int) or max_output_tokens < 1 or max_output_tokens > 32768:
            _log("VALIDATION_ERROR", {"field": "max_output_tokens"})
            return _err("VALIDATION_ERROR", "max_output_tokens must be between 1 and 32768.", field="max_output_tokens")
    if force_regenerate is not None and not isinstance(force_regenerate, bool):
        _log("VALIDATION_ERROR", {"field": "force_regenerate"})
        return _err("VALIDATION_ERROR", "force_regenerate must be a boolean.", field="force_regenerate")
    if force_regenerate is None:
        force_regenerate = False

    # --- Resolve model: requested or default active ---
    catalog = _load("model_catalog.json")
    if not isinstance(catalog, list):
        catalog = []
    chosen_model = None
    if model_id is not None:
        for m in catalog:
            if isinstance(m, dict) and m.get("id") == model_id:
                chosen_model = m
                break
        if chosen_model is None:
            _log("NOT_FOUND", {"reason": "model_not_found", "model_id": model_id})
            return _err("NOT_FOUND", "Model not found.", model_id=model_id)
        if chosen_model.get("status") == "disabled":
            _log("CONFLICT", {"reason": "model_disabled", "model_id": model_id})
            return _err("CONFLICT", "Requested model is disabled.", model_id=model_id)
        if chosen_model.get("provider") != "google_gemini" or chosen_model.get("supports_generate_content") is not True:
            _log("CONFLICT", {"reason": "model_not_supported", "model_id": model_id})
            return _err("CONFLICT", "Requested model does not support generation.", model_id=model_id)
    else:
        for m in catalog:
            if isinstance(m, dict) and m.get("is_default") is True and m.get("status") == "active" and m.get("provider") == "google_gemini" and m.get("supports_generate_content") is True:
                chosen_model = m
                break
        if chosen_model is None:
            for m in catalog:
                if isinstance(m, dict) and m.get("status") in ("active", "deprecated") and m.get("provider") == "google_gemini" and m.get("supports_generate_content") is True:
                    chosen_model = m
                    break
        if chosen_model is None:
            _log("UNAUTHORIZED", {"reason": "no_available_model"})
            return _err("UNAUTHORIZED", "No model is available to serve this request.")
    chosen_model_id = chosen_model.get("id")

    # Default prompt_version if omitted
    if prompt_version is None:
        prompt_version = "sum_v3.2.1"

    # --- Find or create video by youtube_video_id ---
    videos = _load("videos.json")
    if not isinstance(videos, list):
        videos = []
    video = None
    for v in videos:
        if isinstance(v, dict) and v.get("youtube_video_id") == resolved_ytid:
            video = v
            break

    if video is None:
        # enforce unique(youtube_video_id)
        video = {
            "id": _new_id("ytv_vid_"),
            "youtube_video_id": resolved_ytid,
            "source_url": normalized_source_url,
            "title": None,
            "channel_name": None,
            "published_at": None,
            "duration_seconds": None,
            "language_code": None,
            "transcript_text": None,
            "transcript_source": "none",
            "transcript_updated_at": None,
            "status": "new",
            "last_error": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        videos.append(video)
        _save("videos.json", videos)
    else:
        # Best-effort update source_url if new info provided
        if normalized_source_url and not video.get("source_url"):
            video["source_url"] = normalized_source_url
            video["updated_at"] = now_iso
            _save("videos.json", videos)

    if video.get("status") == "deleted":
        _log("INVALID_TRANSITION", {"reason": "video_deleted", "video_id": video.get("id")})
        return _err("INVALID_TRANSITION", "Video is deleted; cannot create new generation jobs.", video_id=video.get("id"))

    # --- Ensure transcript ready ---
    def _transition_allowed(from_s, to_s):
        transitions = {
            "new": ["ingesting", "deleted"],
            "ingesting": ["ready", "failed", "deleted"],
            "ready": ["ingesting", "deleted"],
            "failed": ["ingesting", "deleted"],
            "deleted": []
        }
        return to_s in transitions.get(from_s, [])

    def _ensure_ready(vrow):
        st = vrow.get("status")
        if st == "ready":
            if not vrow.get("transcript_text"):
                # constraint: status ready implies transcript_text not null
                vrow["status"] = "failed"
                vrow["last_error"] = "Invariant violation: ready without transcript_text."
                vrow["updated_at"] = now_iso
                _save("videos.json", videos)
                return False, "Video transcript missing."
            return True, None

        # Must transition to ingesting if not ready
        if st != "ingesting":
            if not _transition_allowed(st, "ingesting"):
                return False, f"Illegal transition from {st} to ingesting."
            vrow["status"] = "ingesting"
            vrow["updated_at"] = now_iso
            _save("videos.json", videos)

        # Attempt transcript acquisition (offline deterministic best-effort)
        # If source_url absent, still succeed with minimal transcript.
        transcript = None
        if isinstance(vrow.get("transcript_text"), str) and vrow.get("transcript_text").strip():
            transcript = vrow.get("transcript_text").strip()
        else:
            transcript = f"Transcript unavailable; generated placeholder for YouTube video {vrow.get('youtube_video_id')}."

        if transcript:
            vrow["transcript_text"] = transcript
            vrow["transcript_source"] = "asr_generated"
            vrow["transcript_updated_at"] = now_iso
            if not _transition_allowed(vrow.get("status"), "ready"):
                return False, f"Illegal transition from {vrow.get('status')} to ready."
            vrow["status"] = "ready"
            vrow["last_error"] = None
            vrow["updated_at"] = now_iso
            _save("videos.json", videos)
            return True, None

        # Fail
        if not _transition_allowed(vrow.get("status"), "failed"):
            return False, f"Illegal transition from {vrow.get('status')} to failed."
        vrow["status"] = "failed"
        vrow["last_error"] = "Transcript acquisition failed."
        vrow["updated_at"] = now_iso
        _save("videos.json", videos)
        return False, vrow["last_error"]

    ok, errm = _ensure_ready(video)
    if not ok:
        _log("CONFLICT", {"reason": "video_not_ready", "video_id": video.get("id"), "error": errm})
        return _err("CONFLICT", "Video is not ready for processing.", video_id=video.get("id"), last_error=video.get("last_error"))

    transcript_hash = _sha256_hex(video.get("transcript_text") or "")

    # --- Cache lookup ---
    artifacts = _load("video_artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []
    cached = None
    if not force_regenerate:
        for a in artifacts:
            if not isinstance(a, dict):
                continue
            if a.get("status") != "active":
                continue
            if a.get("video_id") != video.get("id"):
                continue
            if a.get("artifact_type") != "summary":
                continue
            if a.get("model_id") != chosen_model_id:
                continue
            if a.get("prompt_version") != prompt_version:
                continue
            if a.get("input_transcript_hash") != transcript_hash:
                continue
            cached = a
            break

    if cached is not None:
        _log("OK", {"cached": True, "video_id": video.get("id"), "artifact_id": cached.get("id")})
        return {
            "data": {
                "video": video,
                "artifact": cached,
                "job": None,
                "cached": True
            }
        }

    # --- Idempotent job creation: reuse existing queued/running for same cache key ---
    jobs = _load("generation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    existing_job = None
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("video_id") != video.get("id"):
            continue
        if j.get("job_type") != "summary":
            continue
        if (j.get("question_text") or None) is not None:
            continue
        if j.get("prompt_version") != prompt_version:
            continue
        if j.get("model_id") != chosen_model_id:
            continue
        if j.get("input_transcript_hash") != transcript_hash:
            continue
        if j.get("status") in ("queued", "running"):
            existing_job = j
            break

    if existing_job is None:
        job = {
            "id": _new_id("ytv_job_"),
            "video_id": video.get("id"),
            "job_type": "summary",
            "question_text": None,
            "prompt_version": prompt_version,
            "model_id": chosen_model_id,
            "input_transcript_hash": transcript_hash,
            "temperature": temperature,
            "max_output_tokens": max_output_tokens,
            "status": "queued",
            "started_at": None,
            "finished_at": None,
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        jobs.append(job)
        _save("generation_jobs.json", jobs)
    else:
        job = existing_job

    # Simulate completion (offline): succeed and upsert artifact, respecting transitions and constraints
    def _set_job_status(jrow, new_status, error_message=None):
        transitions = {
            "queued": ["running", "cancelled"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": []
        }
        cur = jrow.get("status")
        if new_status not in transitions.get(cur, []):
            return False, f"Illegal job transition from {cur} to {new_status}."
        jrow["status"] = new_status
        jrow["updated_at"] = now_iso
        if new_status == "running":
            jrow["started_at"] = jrow.get("started_at") or now_iso
        if new_status in ("succeeded", "failed", "cancelled"):
            jrow["started_at"] = jrow.get("started_at") or now_iso
            jrow["finished_at"] = now_iso
        if new_status == "succeeded":
            jrow["error_message"] = None
            if jrow.get("finished_at") is None:
                jrow["finished_at"] = now_iso
        if new_status == "failed":
            jrow["error_message"] = error_message or "Generation failed."
            if jrow.get("finished_at") is None:
                jrow["finished_at"] = now_iso
        return True, None

    # Move queued->running->succeeded
    if job.get("status") == "queued":
        ok1, em1 = _set_job_status(job, "running")
        if not ok1:
            _log("INVALID_TRANSITION", {"reason": "job_transition", "error": em1})
            return _err("INVALID_TRANSITION", em1, job_id=job.get("id"))
        _save("generation_jobs.json", jobs)

    if job.get("status") == "running":
        generated_text = f"Summary for video {video.get('youtube_video_id')}: This video discusses key topics and provides an overview based on the available transcript."
        ok2, em2 = _set_job_status(job, "succeeded")
        if not ok2:
            _log("INVALID_TRANSITION", {"reason": "job_transition", "error": em2})
            return _err("INVALID_TRANSITION", em2, job_id=job.get("id"))
        _save("generation_jobs.json", jobs)

        # supersede prior active summaries for same (video_id, model_id, prompt_version) different hash
        for a in artifacts:
            if not isinstance(a, dict):
                continue
            if a.get("video_id") == video.get("id") and a.get("artifact_type") == "summary" and a.get("status") == "active" and a.get("model_id") == chosen_model_id and a.get("prompt_version") == prompt_version and a.get("input_transcript_hash") != transcript_hash:
                a["status"] = "superseded"
                a["updated_at"] = now_iso

        # upsert active artifact for cache key
        artifact = None
        for a in artifacts:
            if not isinstance(a, dict):
                continue
            if a.get("video_id") == video.get("id") and a.get("artifact_type") == "summary" and a.get("status") == "active" and a.get("model_id") == chosen_model_id and a.get("prompt_version") == prompt_version and a.get("input_transcript_hash") == transcript_hash:
                artifact = a
                break
        if artifact is None:
            artifact = {
                "id": _new_id("ytv_art_"),
                "video_id": video.get("id"),
                "job_id": job.get("id"),
                "artifact_type": "summary",
                "question_text": None,
                "model_id": chosen_model_id,
                "prompt_version": prompt_version,
                "input_transcript_hash": transcript_hash,
                "content_text": generated_text,
                "key_moments": None,
                "status": "active",
                "created_at": now_iso,
                "updated_at": now_iso
            }
            artifacts.append(artifact)
        else:
            artifact["job_id"] = job.get("id")
            artifact["content_text"] = generated_text
            artifact["updated_at"] = now_iso

        _save("video_artifacts.json", artifacts)

        _log("OK", {"cached": False, "video_id": video.get("id"), "artifact_id": artifact.get("id"), "job_id": job.get("id")})
        return {"data": {"video": video, "artifact": artifact, "job": job, "cached": False}}

    _log("CONFLICT", {"reason": "job_not_executed", "job_id": job.get("id"), "status": job.get("status")})
    return _err("CONFLICT", "Generation job did not complete.", job_id=job.get("id"), status=job.get("status"))

def ask_about_youtube_video(youtube_video_id=None, source_url=None, question=None, model_id=None, prompt_version=None, temperature=None, max_output_tokens=None, force_regenerate=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0554000" if __import__("os").path.isdir("./environment_mix/0554000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _new_id(prefix):
        return prefix + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")

    def _log(status, details=None, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("ytv_req_"),
            "endpoint": "ask_about_youtube_video",
            "status": status,
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id
        }
        if details is not None:
            row["details"] = details
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_youtube_id(url):
        if not isinstance(url, str) or not url.strip():
            return None
        try:
            u = urllib.parse.urlparse(url.strip())
        except Exception:
            return None
        host = (u.netloc or "").lower()
        path = u.path or ""
        q = urllib.parse.parse_qs(u.query or "")
        if "youtu.be" in host:
            seg = path.strip("/").split("/")
            return seg[0] if seg and seg[0] else None
        if "youtube.com" in host or "m.youtube.com" in host:
            if "v" in q and q["v"] and q["v"][0]:
                return q["v"][0]
            m = re.match(r"^/shorts/([^/?#]+)", path)
            if m:
                return m.group(1)
            m = re.match(r"^/embed/([^/?#]+)", path)
            if m:
                return m.group(1)
        return None

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _normalize_question(q):
        if q is None:
            return None
        if not isinstance(q, str):
            return "__INVALID__"
        q2 = " ".join(q.strip().split())
        return None if q2 == "" else q2

    # Validate oneOf: allow both when consistent
    if youtube_video_id is None and source_url is None:
        _log("VALIDATION_ERROR", {"reason": "missing_youtube_video_id_or_source_url"})
        return _err("VALIDATION_ERROR", "Provide either youtube_video_id or source_url.")
    if youtube_video_id is not None and not isinstance(youtube_video_id, str):
        _log("VALIDATION_ERROR", {"field": "youtube_video_id"})
        return _err("VALIDATION_ERROR", "youtube_video_id must be a string.", field="youtube_video_id")
    if source_url is not None and not isinstance(source_url, str):
        _log("VALIDATION_ERROR", {"field": "source_url"})
        return _err("VALIDATION_ERROR", "source_url must be a string.", field="source_url")

    ytid_from_url = _parse_youtube_id(source_url) if source_url is not None else None
    if youtube_video_id is not None and source_url is not None:
        if ytid_from_url is None:
            _log("VALIDATION_ERROR", {"reason": "unparseable_source_url"})
            return _err("VALIDATION_ERROR", "source_url is not a recognized YouTube URL.", field="source_url")
        if youtube_video_id.strip() != ytid_from_url:
            _log("VALIDATION_ERROR", {"reason": "youtube_video_id_source_url_mismatch", "parsed": ytid_from_url})
            return _err("VALIDATION_ERROR", "youtube_video_id and source_url refer to different videos.", field="source_url")
        resolved_ytid = youtube_video_id.strip()
        normalized_source_url = source_url.strip()
    elif youtube_video_id is not None:
        resolved_ytid = youtube_video_id.strip()
        normalized_source_url = None
    else:
        if ytid_from_url is None:
            _log("VALIDATION_ERROR", {"reason": "unparseable_source_url"})
            return _err("VALIDATION_ERROR", "source_url is not a recognized YouTube URL.", field="source_url")
        resolved_ytid = ytid_from_url
        normalized_source_url = source_url.strip()

    nq = _normalize_question(question)
    if nq == "__INVALID__":
        _log("VALIDATION_ERROR", {"field": "question"})
        return _err("VALIDATION_ERROR", "question must be a string.", field="question")

    # Validate model/prompt/gen settings
    if model_id is not None:
        if not isinstance(model_id, str) or not re.match(r"^ytv_mdl_01H[0-9A-Z]{15,}$", model_id):
            _log("VALIDATION_ERROR", {"field": "model_id"})
            return _err("VALIDATION_ERROR", "model_id has invalid format.", field="model_id")
    if prompt_version is not None and not isinstance(prompt_version, str):
        _log("VALIDATION_ERROR", {"field": "prompt_version"})
        return _err("VALIDATION_ERROR", "prompt_version must be a string.", field="prompt_version")
    if temperature is not None:
        if not isinstance(temperature, (int, float)) or temperature < 0.0 or temperature > 2.0:
            _log("VALIDATION_ERROR", {"field": "temperature"})
            return _err("VALIDATION_ERROR", "temperature must be between 0.0 and 2.0.", field="temperature")
        temperature = float(temperature)
    if max_output_tokens is not None:
