        if j.get("prompt_version") != prompt_version:
            continue
        if j.get("model_id") != chosen_model_id:
            continue
        if j.get("input_transcript_hash") != transcript_hash:
            continue
        if j.get("status") in ("queued", "running"):
            existing_job = j
            break

    if existing_job is None:
        job = {
            "id": _new_id("ytv_job_"),
            "video_id": video.get("id"),
            "job_type": "key_moments",
            "question_text": None,
            "prompt_version": prompt_version,
            "model_id": chosen_model_id,
            "input_transcript_hash": transcript_hash,
            "temperature": temperature,
            "max_output_tokens": max_output_tokens,
            "status": "queued",
            "started_at": None,
            "finished_at": None,
            "error_message": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        jobs.append(job)
        _save("generation_jobs.json", jobs)
    else:
        job = existing_job

    # Execute offline and create moments
    transitions_job = {
        "queued": ["running", "cancelled"],
        "running": ["succeeded", "failed", "cancelled"],
        "succeeded": [],
        "failed": [],
        "cancelled": []
    }

    def _job_transition(jrow, to_status, error_message=None):
        frm = jrow.get("status")
        if to_status not in transitions_job.get(frm, []):
            return False, f"Illegal job transition from {frm} to {to_status}."
        jrow["status"] = to_status
        jrow["updated_at"] = now_iso
        if to_status == "running":
            jrow["started_at"] = jrow.get("started_at") or now_iso
        if to_status in ("succeeded", "failed", "cancelled"):
            jrow["started_at"] = jrow.get("started_at") or now_iso
            jrow["finished_at"] = now_iso
        if to_status == "succeeded":
            jrow["error_message"] = None
        if to_status == "failed":
            jrow["error_message"] = error_message or "Generation failed."
        return True, None

    if job.get("status") == "queued":
        ok1, em1 = _job_transition(job, "running")
        if not ok1:
            _log("INVALID_TRANSITION", {"reason": "job_transition", "error": em1})
            return _err("INVALID_TRANSITION", em1, job_id=job.get("id"))
        _save("generation_jobs.json", jobs)

    if job.get("status") == "running":
        # simple structured moments; ensure timestamp_seconds >= 0
        moments = [
            {"timestamp_seconds": 0, "title": "Intro", "description": "Opening context and overview."},
            {"timestamp_seconds": 60, "title": "Main point", "description": "Core discussion based on transcript."},
            {"timestamp_seconds": 120, "title": "Wrap-up", "description": "Summary and closing remarks."}
        ]
        moments = [m for m in moments if isinstance(m, dict) and isinstance(m.get("timestamp_seconds"), int) and m["timestamp_seconds"] >= 0]

        ok2, em2 = _job_transition(job, "succeeded")
        if not ok2:
            _log("INVALID_TRANSITION", {"reason": "job_transition", "error": em2})
            return _err("INVALID_TRANSITION", em2, job_id=job.get("id"))
        _save("generation_jobs.json", jobs)

        # supersede prior active key_moments for same (video_id, model_id, prompt_version) different hash
        for a in artifacts:
            if not isinstance(a, dict):
                continue
            if a.get("video_id") == video.get("id") and a.get("artifact_type") == "key_moments" and a.get("status") == "active" and a.get("model_id") == chosen_model_id and a.get("prompt_version") == prompt_version and a.get("input_transcript_hash") != transcript_hash:
                a["status"] = "superseded"
                a["updated_at"] = now_iso

        artifact = None
        for a in artifacts:
            if not isinstance(a, dict):
                continue
            if a.get("video_id") == video.get("id") and a.get("artifact_type") == "key_moments" and a.get("status") == "active" and a.get("model_id") == chosen_model_id and a.get("prompt_version") == prompt_version and a.get("input_transcript_hash") == transcript_hash:
                artifact = a
                break
        if artifact is None:
            artifact = {
                "id": _new_id("ytv_art_"),
                "video_id": video.get("id"),
                "job_id": job.get("id"),
                "artifact_type": "key_moments",
                "question_text": None,
                "model_id": chosen_model_id,
                "prompt_version": prompt_version,
                "input_transcript_hash": transcript_hash,
                "content_text": None,
                "key_moments": moments,
                "status": "active",
                "created_at": now_iso,
                "updated_at": now_iso
            }
            artifacts.append(artifact)
        else:
            artifact["job_id"] = job.get("id")
            artifact["key_moments"] = moments
            artifact["updated_at"] = now_iso

        _save("video_artifacts.json", artifacts)
        _log("OK", {"cached": False, "video_id": video.get("id"), "artifact_id": artifact.get("id"), "job_id": job.get("id")})
        return {"data": {"video": video, "artifact": artifact, "job": job, "cached": False}}

    _log("CONFLICT", {"reason": "job_not_executed", "job_id": job.get("id"), "status": job.get("status")})
    return _err("CONFLICT", "Generation job did not complete.", job_id=job.get("id"), status=job.get("status"))

def list_supported_models(provider=None, status=None, is_default=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0554000" if __import__("os").path.isdir("./environment_mix/0554000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status2, endpoint, details=None):
        logs = _load("request_logs.json")
        row = {
            "id": "ytv_req_" + base64.b32encode(os.urandom(10)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": status2,
            "timestamp": _now,
            "latency_ms": int((time.time() - _t0) * 1000),
        }
        if details is not None:
            row["details"] = details
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if provider is not None and provider != "google_gemini":
        _log("error", "list_supported_models", {"field": "provider"})
        return _err("VALIDATION_ERROR", "provider must be 'google_gemini' if provided.")
    if status is not None and status not in ("active", "deprecated", "disabled"):
        _log("error", "list_supported_models", {"field": "status"})
        return _err("VALIDATION_ERROR", "status must be one of: active, deprecated, disabled.")
    if is_default is not None and not isinstance(is_default, bool):
        _log("error", "list_supported_models", {"field": "is_default"})
        return _err("VALIDATION_ERROR", "is_default must be a boolean.")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("error", "list_supported_models", {"field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    else:
        limit = 50
    if cursor is not None and not isinstance(cursor, str):
        _log("error", "list_supported_models", {"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # Decode cursor: base64url of integer offset
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            offset = int(base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("error", "list_supported_models", {"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    rows = _load("model_catalog.json")

    # Base filter per business rule: provider=google_gemini, supports_generate_content=true, status in (active, deprecated); never return disabled.
    out = []
    for m in rows:
        if m.get("provider") != "google_gemini":
            continue
        if m.get("supports_generate_content") is not True:
            continue
        if m.get("status") not in ("active", "deprecated"):
            continue
        out.append(m)

    # Apply optional filters (status filter cannot widen to disabled because base rule prohibits)
    if provider is not None:
        out = [m for m in out if m.get("provider") == provider]
    if status is not None:
        # If user asks disabled, return empty set (not an error) due to service rule.
        out = [m for m in out if m.get("status") == status]
    if is_default is not None:
        out = [m for m in out if m.get("is_default") is is_default]

    # Deterministic sort: default first, then provider/model_name, then id
    def _key(m):
        return (0 if m.get("is_default") else 1, m.get("provider") or "", m.get("model_name") or "", m.get("id") or "")
    out.sort(key=_key)

    total = len(out)
    page = out[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_off).encode("utf-8")).decode("ascii").rstrip("=")

    _log("ok", "list_supported_models", {"returned": len(page), "total": total, "has_more": has_more})
    return {
        "models": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def list_videos(status=None, youtube_video_id=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0554000" if __import__("os").path.isdir("./environment_mix/0554000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _cursor_decode(c):
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if obj.get("v") != 1:
                return None
            if not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                return None
            return obj
        except Exception:
            return None

    def _cursor_encode(offset):
        payload = {"v": 1, "offset": offset}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # --- rate limit / request log (best-effort if file exists) ---
    def _log_and_enforce(endpoint, status_code):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        limit_per_min = 120
        cutoff = (now - datetime.timedelta(seconds=window_s)).isoformat()
        recent = 0
        for r in logs:
            if isinstance(r, dict) and r.get("endpoint") == endpoint:
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
        # log first? real services enforce before charging; we enforce before and still log the rejected request
        if recent >= limit_per_min and status_code != "RATE_LIMIT":
            entry = {"id": f"req_{len(logs)+1}", "endpoint": endpoint, "credential_id": None, "status": "RATE_LIMIT", "latency_ms": 0, "timestamp": now.isoformat()}
            logs.append(entry)
            _save("request_logs.json", logs)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        entry = {"id": f"req_{len(logs)+1}", "endpoint": endpoint, "credential_id": None, "status": status_code, "latency_ms": 0, "timestamp": now.isoformat()}
        logs.append(entry)
        _save("request_logs.json", logs)
        return None

    endpoint = "list_videos"

    # --- validate inputs ---
    allowed_status = {"new", "ingesting", "ready", "failed", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            e = _log_and_enforce(endpoint, "VALIDATION_ERROR")
            return e if e else _err("VALIDATION_ERROR", "Invalid status filter", field="status")
    if youtube_video_id is not None and not isinstance(youtube_video_id, str):
        e = _log_and_enforce(endpoint, "VALIDATION_ERROR")
        return e if e else _err("VALIDATION_ERROR", "youtube_video_id must be a string", field="youtube_video_id")
    ca = _parse_rfc3339(created_after)
    if created_after is not None and ca is None:
        e = _log_and_enforce(endpoint, "VALIDATION_ERROR")
        return e if e else _err("VALIDATION_ERROR", "created_after must be RFC3339 date-time", field="created_after")
    cb = _parse_rfc3339(created_before)
    if created_before is not None and cb is None:
        e = _log_and_enforce(endpoint, "VALIDATION_ERROR")
        return e if e else _err("VALIDATION_ERROR", "created_before must be RFC3339 date-time", field="created_before")
    if ca is not None and cb is not None and ca > cb:
        e = _log_and_enforce(endpoint, "VALIDATION_ERROR")
        return e if e else _err("VALIDATION_ERROR", "created_after must be <= created_before")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _log_and_enforce(endpoint, "VALIDATION_ERROR")
        return e if e else _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            e = _log_and_enforce(endpoint, "VALIDATION_ERROR")
            return e if e else _err("VALIDATION_ERROR", "cursor must be a non-empty string", field="cursor")
        decoded = _cursor_decode(cursor)
        if decoded is None:
            e = _log_and_enforce(endpoint, "VALIDATION_ERROR")
            return e if e else _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        offset = decoded["offset"]

    # enforce rate limit (if logs exist)
    rate_err = _log_and_enforce(endpoint, "OK_PENDING")  # temporary marker; will be overwritten with final status
    if isinstance(rate_err, dict) and "error" in rate_err:
        return rate_err

    # --- load and filter ---
    rows = _load("videos.json")
    if not isinstance(rows, list):
        rows = []

    def _row_dt(r, k):
        v = r.get(k)
        if not isinstance(v, str):
            return None
        return _parse_rfc3339(v)

    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        st = r.get("status")
        if status is None:
            if st == "deleted":
                continue
        else:
            if st != status:
                continue
        if youtube_video_id is not None and r.get("youtube_video_id") != youtube_video_id:
            continue
        if ca is not None:
            d = _row_dt(r, "created_at")
            if d is None or d <= ca:
                continue
        if cb is not None:
            d = _row_dt(r, "created_at")
            if d is None or d >= cb:
                continue
        out.append(r)

    # stable sort by created_at desc then id desc
    def _sort_key(r):
        d = _row_dt(r, "created_at")
        if d is None:
            d = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (d, str(r.get("id") or ""))
    out.sort(key=_sort_key, reverse=True)

    total = len(out)
    page = out[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _cursor_encode(next_offset) if has_more else None

    # update request log final status if present
    logs = _load("request_logs.json")
    if isinstance(logs, list) and logs:
        if isinstance(logs[-1], dict) and logs[-1].get("endpoint") == endpoint and logs[-1].get("status") == "OK_PENDING":
            logs[-1]["status"] = "OK"
            _save("request_logs.json", logs)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_video(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0554000" if __import__("os").path.isdir("./environment_mix/0554000") else "/app/database")
    def _load(n):
