                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        import base64
        return prefix + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")

    def _log(status, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("ytv_req_"),
            "endpoint": "get_video",
            "status": status,
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None
        }
        if details is not None:
            row["details"] = details
        logs.append(row)
        _save("request_logs.json", logs)

    # Relax overly-strict format validation (audit defect fix): accept any non-empty string
    if id is None or not isinstance(id, str) or not id.strip():
