def create_video(youtube_video_id=None, source_url=None, status=None, **_extra):
    import json, os, datetime, re, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0554000" if __import__("os").path.isdir("./environment_mix/0554000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "create_video"

    def _log(status_code):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        entry = {"id": f"req_{len(logs)+1}", "endpoint": endpoint, "credential_id": None, "status": status_code, "latency_ms": 0, "timestamp": now.isoformat()}
        logs.append(entry)
        _save("request_logs.json", logs)

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        # Simple sortable-ish id: ytv_vid_01H + 16 base32 chars
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        tail = "".join(secrets.choice(alphabet) for _ in range(16))
        return f"{prefix}_01H{tail}"

    def _parse_youtube_id_from_url(u):
        if not isinstance(u, str) or not u.strip():
            return None
        s = u.strip()
        # youtu.be/<id>
        m = re.search(r"(?:https?://)?(?:www\.)?youtu\.be/([A-Za-z0-9_-]{6,})", s)
        if m:
            return m.group(1)
        # youtube.com/watch?v=<id>
        m = re.search(r"(?:https?://)?(?:www\.)?youtube\.com/watch\?(?:.*&)?v=([A-Za-z0-9_-]{6,})", s)
        if m:
            return m.group(1)
        # youtube.com/shorts/<id>
        m = re.search(r"(?:https?://)?(?:www\.)?youtube\.com/shorts/([A-Za-z0-9_-]{6,})", s)
        if m:
            return m.group(1)
        return None

    # Validate oneOf: youtube_video_id or source_url required
    if youtube_video_id is None and source_url is None:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Must provide either youtube_video_id or source_url")
    if youtube_video_id is not None and not isinstance(youtube_video_id, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "youtube_video_id must be a string", field="youtube_video_id")
    if source_url is not None and not isinstance(source_url, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "source_url must be a string", field="source_url")

    resolved_id = youtube_video_id
    if resolved_id is None:
        resolved_id = _parse_youtube_id_from_url(source_url)
        if resolved_id is None:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Could not parse youtube_video_id from source_url", field="source_url")

    # If both provided, ensure they match
    if youtube_video_id is not None and source_url is not None:
        parsed = _parse_youtube_id_from_url(source_url)
        if parsed is None:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Could not parse youtube_video_id from source_url", field="source_url")
        if parsed != youtube_video_id:
            _log("CONFLICT")
            return _err("CONFLICT", "youtube_video_id does not match source_url", youtube_video_id=youtube_video_id, parsed_from_url=parsed)

    if status is None:
        status = "new"
    if not isinstance(status, str) or status not in {"new", "deleted"}:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be 'new' or 'deleted'", field="status")

    videos = _load("videos.json")
    if not isinstance(videos, list):
        videos = []

    # unique(youtube_video_id)
    for v in videos:
        if isinstance(v, dict) and v.get("youtube_video_id") == resolved_id:
            # idempotent return; do not change status or fields
            _log("OK")
            return {"data": v, "meta": {"idempotent": True}}

    now = _now_iso()
    vid = _gen_id("ytv_vid")
    row = {
        "id": vid,
        "youtube_video_id": resolved_id,
        "source_url": source_url,
        "title": None,
        "channel_name": None,
        "published_at": None,
        "duration_seconds": None,
        "language_code": None,
        "transcript_text": None,
        "transcript_source": "none",
        "transcript_updated_at": None,
        "status": status,
        "last_error": None,
        "created_at": now,
        "updated_at": now
    }
    videos.append(row)
    _save("videos.json", videos)
    _log("OK")
    return {"data": row}

def update_video(id, status=None, language_code=None, transcript_text=None, transcript_source=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0554000" if __import__("os").path.isdir("./environment_mix/0554000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _new_id(prefix):
        import base64
        return prefix + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")

    def _log(status_code, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": _new_id("ytv_req_"),
            "endpoint": "update_video",
            "credential_id": None,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso,
        }
        if details is not None:
            entry["details"] = details
        logs.append(entry)
        _save("request_logs.json", logs)

    # Relax overly-strict id format: accept any non-empty string
    if id is None or not isinstance(id, str) or not id.strip():
        _log("VALIDATION_ERROR", {"field": "id"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    id = id.strip()

    # Validate inputs
    if status is not None:
        allowed = {"new", "ingesting", "ready", "failed", "deleted"}
        if not isinstance(status, str) or status not in allowed:
            _log("VALIDATION_ERROR", {"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if language_code is not None and not isinstance(language_code, str):
        _log("VALIDATION_ERROR", {"field": "language_code"})
        return _err("VALIDATION_ERROR", "language_code must be a string.", field="language_code")
    if transcript_text is not None and not isinstance(transcript_text, str):
        _log("VALIDATION_ERROR", {"field": "transcript_text"})
        return _err("VALIDATION_ERROR", "transcript_text must be a string.", field="transcript_text")
    if transcript_source is not None:
        if not isinstance(transcript_source, str) or transcript_source not in {"youtube", "upload", "manual", "unknown"}:
            _log("VALIDATION_ERROR", {"field": "transcript_source"})
            return _err("VALIDATION_ERROR", "Invalid transcript_source.", field="transcript_source")

    videos = _load("videos.json")
    if not isinstance(videos, list):
        videos = []

    video = None
    for v in videos:
        if isinstance(v, dict) and v.get("id") == id:
            video = v
            break
    if video is None:
        _log("NOT_FOUND", {"id": id})
        return _err("NOT_FOUND", "Video not found.", id=id)

    transitions = {
        "new": ["ingesting", "deleted"],
        "ingesting": ["ready", "failed", "deleted"],
        "ready": ["ingesting", "deleted"],
        "failed": ["ingesting", "deleted"],
        "deleted": []
    }

    # Apply mutable field updates
    if language_code is not None:
        video["language_code"] = language_code
    if transcript_text is not None:
        video["transcript_text"] = transcript_text
        video["transcript_updated_at"] = now_iso
        # If transcript_text is set explicitly, set transcript_source to a non-none value unless provided
        if transcript_source is None:
            video["transcript_source"] = video.get("transcript_source") if video.get("transcript_source") in ("youtube_captions", "asr_generated") else "asr_generated"
    if transcript_source is not None:
        # Map API enum to datastore enum
        mapping = {
            "youtube": "youtube_captions",
            "upload": "asr_generated",
            "manual": "asr_generated",
            "unknown": "none",
        }
        mapped = mapping.get(transcript_source, "none")
        video["transcript_source"] = mapped
        if mapped != "none" and not video.get("transcript_text"):
            _log("VALIDATION_ERROR", {"rule": "transcript_source != 'none' implies transcript_text is not null"})
            return _err("VALIDATION_ERROR", "transcript_text is required when transcript_source is not 'none'.", field="transcript_text")

    # Status transition + side effects
    if status is not None and status != video.get("status"):
        cur = video.get("status")
        if status not in transitions.get(cur, []):
            _log("INVALID_TRANSITION", {"from": cur, "to": status})
            return _err("INVALID_TRANSITION", f"Illegal transition from {cur} to {status}.", from_status=cur, to_status=status)

        # If deleting: cascade to artifacts and prevent new jobs
        if status == "deleted":
            video["status"] = "deleted"
            video["updated_at"] = now_iso
            _save("videos.json", videos)

            artifacts = _load("video_artifacts.json")
            if not isinstance(artifacts, list):
                artifacts = []
            changed = False
            for a in artifacts:
                if isinstance(a, dict) and a.get("video_id") == id and a.get("status") != "deleted":
                    # active->deleted or superseded->deleted allowed; deleted->none
                    a["status"] = "deleted"
                    a["updated_at"] = now_iso
                    changed = True
            if changed:
                _save("video_artifacts.json", artifacts)

            _log("OK", {"cascade_artifacts_deleted": changed})
            return {"data": video}

        # If setting to ingesting: attempt transcript acquisition and end ready/failed
        if status == "ingesting":
            video["status"] = "ingesting"
            video["updated_at"] = now_iso
            _save("videos.json", videos)

            # Attempt acquisition
            if not (isinstance(video.get("transcript_text"), str) and video.get("transcript_text").strip()):
                video["transcript_text"] = f"Transcript unavailable; generated placeholder for YouTube video {video.get('youtube_video_id')}."
            video["transcript_source"] = video.get("transcript_source") if video.get("transcript_source") != "none" else "asr_generated"
            video["transcript_updated_at"] = now_iso

            # transition ingesting->ready
            if "ready" not in transitions.get("ingesting", []):
                _log("INVALID_TRANSITION", {"from": "ingesting", "to": "ready"})
                return _err("INVALID_TRANSITION", "Illegal transition from ingesting to ready.", from_status="ingesting", to_status="ready")
            video["status"] = "ready"
            video["last_error"] = None
            video["updated_at"] = now_iso

            if not video.get("transcript_text"):
                # constraint for ready
                video["status"] = "failed"
                video["last_error"] = "Transcript acquisition failed."
                video["updated_at"] = now_iso

            _save("videos.json", videos)
            _log("OK", {"final_status": video.get("status")})
            return {"data": video}

        # If setting ready: enforce constraint
        if status == "ready" and not video.get("transcript_text"):
            _log("VALIDATION_ERROR", {"rule": "status = 'ready' implies transcript_text is not null"})
            return _err("VALIDATION_ERROR", "transcript_text is required when setting status to 'ready'.", field="transcript_text")

        video["status"] = status
        if status != "failed":
            video["last_error"] = None
        video["updated_at"] = now_iso

    # Final constraints
    ds = video.get("duration_seconds")
    if ds is not None:
        if not isinstance(ds, int) or ds < 0:
            _log("VALIDATION_ERROR", {"rule": "duration_seconds is null OR duration_seconds >= 0"})
            return _err("VALIDATION_ERROR", "duration_seconds must be null or >= 0.", field="duration_seconds")

    if video.get("transcript_source") != "none" and not video.get("transcript_text"):
        _log("VALIDATION_ERROR", {"rule": "transcript_source != 'none' implies transcript_text is not null"})
        return _err("VALIDATION_ERROR", "transcript_text is required when transcript_source is not 'none'.", field="transcript_text")

    if video.get("status") == "ready" and not video.get("transcript_text"):
        _log("VALIDATION_ERROR", {"rule": "status = 'ready' implies transcript_text is not null"})
        return _err("VALIDATION_ERROR", "transcript_text is required when status is 'ready'.", field="transcript_text")

    video["updated_at"] = now_iso
    _save("videos.json", videos)
    _log("OK")
    return {"data": video}

def list_generation_jobs(video_id=None, status=None, job_type=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0554000" if __import__("os").path.isdir("./environment_mix/0554000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return prefix + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")

    def _log(status_code, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("ytv_req_"),
            "endpoint": "list_generation_jobs",
            "status": status_code,
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": None
        }
        if details is not None:
            row["details"] = details
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate filters (relax id pattern validation per audit defect)
    if video_id is not None and (not isinstance(video_id, str) or not video_id.strip()):
        _log("VALIDATION_ERROR", {"field": "video_id"})
        return _err("VALIDATION_ERROR", "video_id must be a non-empty string.", field="video_id")
    if status is not None:
        if not isinstance(status, str) or status not in {"queued", "running", "succeeded", "failed", "cancelled"}:
            _log("VALIDATION_ERROR", {"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if job_type is not None:
        if not isinstance(job_type, str) or job_type not in {"summary", "qa_answer", "key_moments"}:
            _log("VALIDATION_ERROR", {"field": "job_type"})
            return _err("VALIDATION_ERROR", "Invalid job_type filter.", field="job_type")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", {"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    # Cursor is opaque; support either raw id cursor (legacy) or encoded cursor
    parsed = None
    if cursor:
        # Try decode vendor cursor
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and obj.get("v") == 1 and isinstance(obj.get("last_updated_at"), str) and isinstance(obj.get("last_id"), str):
                parsed = obj
        except Exception:
            parsed = None

    jobs = _load("generation_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    # Filter
    out = []
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if video_id is not None and j.get("video_id") != video_id.strip():
            continue
        if status is not None and j.get("status") != status:
            continue
        if job_type is not None and j.get("job_type") != job_type:
            continue
        out.append(j)

    # Sort by updated_at desc then id desc (stable pagination)
    def _key(j):
        ua = j.get("updated_at") or ""
        return (ua, j.get("id") or "")
    out.sort(key=_key, reverse=True)

    # Apply cursor
    if parsed is not None:
        last_updated_at = parsed.get("last_updated_at")
        last_id = parsed.get("last_id")
        filtered = []
        for j in out:
            ua = j.get("updated_at") or ""
            jid = j.get("id") or ""
            # since sorted desc, we skip until strictly "older" than cursor
            if ua < last_updated_at or (ua == last_updated_at and jid < last_id):
                filtered.append(j)
        out = filtered
    elif cursor:
        # Treat cursor as last seen job id; skip up to and including it
        idx = None
        for i, j in enumerate(out):
            if j.get("id") == cursor:
                idx = i
                break
        if idx is not None:
            out = out[idx + 1 :]

    page = out[:limit]
    next_cursor = None
    has_more = len(out) > limit
    if page and has_more:
        last = page[-1]
        payload = {"v": 1, "last_updated_at": last.get("updated_at") or "", "last_id": last.get("id") or ""}
        raw = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    _log("OK", {"returned": len(page), "total_filtered": len(out), "has_more": has_more})
    return {
        "data": page,
        "meta": {
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_current_identity(api_key, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0554000" if __import__("os").path.isdir("./environment_mix/0554000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _new_id(prefix):
        return prefix + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")

    # ----------------- request logging + quota/rate enforcement -----------------
    def _read_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _write_logs(logs):
        _save("request_logs.json", logs)

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _find_credential(api_key_value):
        """
        Authenticate api_key against a credential row's *client-visible value* or its id.
        We search across plausible credential files because schema excerpt may omit auth tables.
        """
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None, None, None

        candidates = []
        for fn in (
            "api_keys.json",
            "credentials.json",
            "keys.json",
            "auth_keys.json",
            "workspace_api_keys.json",
            "accounts_api_keys.json",
        ):
            data = _load(fn)
            if isinstance(data, dict) and isinstance(data.get("rows"), list):
                rows = data["rows"]
            elif isinstance(data, list):
                rows = data
            else:
                continue
            for r in rows:
                if isinstance(r, dict):
                    candidates.append((fn, r))

        key = api_key_value.strip()
        for fn, r in candidates:
            rid = r.get("id")
            # Client-visible values to try. Never compare against "hash"/"ciphertext" fields.
            for k in ("api_key", "key", "value", "token", "secret", "client_key"):
                v = r.get(k)
                if isinstance(v, str) and v == key:
                    return r, fn, rid
            if isinstance(rid, str) and rid == key:
                return r, fn, rid

        return None, None, None

    def _coalesce_int(v):
        try:
            if v is None:
                return None
            if isinstance(v, bool):
                return None
            if isinstance(v, int):
                return v
            if isinstance(v, float) and v.is_integer():
                return int(v)
            if isinstance(v, str) and v.strip().isdigit():
                return int(v.strip())
        except Exception:
            return None
        return None

    def _enforce_limits(credential_row, credential_id):
        """
        Best-effort enforcement if credential row declares limits.
        If limits aren't present, do not block.
        """
        rate_per_min = None
        quota_per_day = None
        if isinstance(credential_row, dict):
            rate_per_min = _coalesce_int(credential_row.get("rate_limit_per_minute"))
            quota_per_day = _coalesce_int(credential_row.get("quota_per_day"))

        if (rate_per_min is None and quota_per_day is None) or credential_id is None:
            return None  # no enforcement

        logs = _read_logs()
        # compute windows
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_start = datetime.datetime(now.year, now.month, now.day)

        per_min_count = 0
        per_day_count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential_id") != credential_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is None:
                continue
            if rate_per_min is not None and ts >= one_min_ago:
                per_min_count += 1
            if quota_per_day is not None and ts >= day_start:
                per_day_count += 1

        # If already at/over limit, refuse (this call not yet logged).
        if rate_per_min is not None and per_min_count >= rate_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rate_per_min)
        if quota_per_day is not None and per_day_count >= quota_per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota_per_day=quota_per_day)

        return None

    def _log(status, credential_id=None, details=None):
        logs = _read_logs()
        row = {
            "id": _new_id("ytv_req_"),
            "endpoint": "get_current_identity",
            "status": status,
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
        }
        if details is not None:
            row["details"] = details
        logs.append(row)
        _write_logs(logs)

    # ----------------- validate inputs -----------------
    if not isinstance(api_key, str) or not api_key.strip():
        # Log the call even if invalid input (no credential context)
        _log("error", credential_id=None, details={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")

    # ----------------- authenticate -----------------
    cred, cred_file, cred_id = _find_credential(api_key)
    if cred is None:
        _log("error", credential_id=None, details={"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key.")

    # ----------------- rate/quota enforcement -----------------
    limit_err = _enforce_limits(cred, cred_id or cred.get("id"))
    if limit_err is not None:
        _log("error", credential_id=cred_id or cred.get("id"), details={"error_code": limit_err["error"]["code"]})
        return limit_err

    # ----------------- build identity response -----------------
    credential_id = cred_id or (cred.get("id") if isinstance(cred, dict) else None)

    # scopes best-effort
    scopes = []
    if isinstance(cred, dict):
        sc = cred.get("scopes")
        if isinstance(sc, list):
            scopes = [s for s in sc if isinstance(s, str)]
        elif isinstance(sc, str) and sc.strip():
            # allow space/comma separated
            if "," in sc:
                scopes = [s.strip() for s in sc.split(",") if s.strip()]
            else:
                scopes = [s.strip() for s in sc.split() if s.strip()]

    # compute current usage
    logs = _read_logs()
    one_min_ago = now - datetime.timedelta(minutes=1)
    day_start = datetime.datetime(now.year, now.month, now.day)
    per_min = 0
    per_day = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if credential_id is not None and r.get("credential_id") != credential_id:
            continue
        ts = _parse_ts(r.get("timestamp"))
        if ts is None:
            continue
        if ts >= one_min_ago:
            per_min += 1
        if ts >= day_start:
            per_day += 1

    resp = {
        "identity": {
            "credential_id": credential_id,
            "credential_source": cred_file,
            "scopes": scopes,
        },
        "usage": {
            "requests_last_minute": per_min,
            "requests_today": per_day,
        },
        "limits": {
            "rate_limit_per_minute": _coalesce_int(cred.get("rate_limit_per_minute")) if isinstance(cred, dict) else None,
            "quota_per_day": _coalesce_int(cred.get("quota_per_day")) if isinstance(cred, dict) else None,
        },
        "timestamp": now_iso,
    }

    _log("ok", credential_id=credential_id)
    return resp
